pub fn atoi_i32(input: &str) -> i32 {
    let bytes = input.as_bytes();
    let mut index = 0usize;

    while index < bytes.len() && bytes[index].is_ascii_whitespace() {
        index += 1;
    }

    let mut negative = false;
    if index < bytes.len() {
        match bytes[index] {
            b'+' => index += 1,
            b'-' => {
                negative = true;
                index += 1;
            }
            _ => {}
        }
    }

    let mut value = 0i64;
    let mut saw_digit = false;
    while index < bytes.len() {
        let byte = bytes[index];
        if !byte.is_ascii_digit() {
            break;
        }

        saw_digit = true;
        value = value
            .saturating_mul(10)
            .saturating_add(i64::from(byte - b'0'));
        index += 1;
    }

    if !saw_digit {
        return 0;
    }

    let signed = if negative { -value } else { value };
    match i32::try_from(signed) {
        Ok(parsed) => parsed,
        Err(_) if negative => i32::MIN,
        Err(_) => i32::MAX,
    }
}

#[cfg(test)]
mod tests {
    use super::atoi_i32;

    #[test]
    fn parses_like_atoi_for_common_inputs() {
        assert_eq!(atoi_i32("12xyz"), 12);
        assert_eq!(atoi_i32("+5"), 5);
        assert_eq!(atoi_i32("-3"), -3);
        assert_eq!(atoi_i32("abc"), 0);
        assert_eq!(atoi_i32("   7"), 7);
    }
}

